// zu — isiZulu (zulu).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// ---------------------------------------------------------------------------------------------------
// CONFIANÇA MÉDIA. O zulu tem bem menos texto de onde eu tenha aprendido do que as línguas grandes, e
// ninguém da dupla o lê. O erro provável é de CONCORDÂNCIA (cada classe de substantivo puxa o próprio
// prefixo no adjetivo, no número e no verbo), não de sentido. Se aparecer quem fale zulu, a revisão
// vale mais que este arquivo.
// ---------------------------------------------------------------------------------------------------
//
// TOM: **wena**, o singular. Em zulu o plural de respeito (nina, "Khethani") é o que se usa com os
// mais velhos; entre iguais, e com quem acabou de chegar, o singular é o neutro — e é o que as
// interfaces em zulu usam ("Khetha", "Londoloza"). Aqui a forma cortês do resto do mundo seria a
// cerimoniosa.
//
// GÊNERO: NENHUM. O zulu não tem sexo gramatical: tem CLASSES de substantivo (um-/aba-, isi-/izi-,
// i-/ama-…), e "ele" e "ela" são a mesma palavra (yena).
//
// NÚMEROS vêm DEPOIS do substantivo e concordam com a classe dele: imilayezo engu-5, abantu abangu-5,
// izinsuku ezingu-7, amalungu angu-15. O hífen antes do algarismo é a ortografia do zulu, não enfeite.
// Algarismos 0-9, que é o que o Intl desenha.
//
// NOME ESTRANGEIRO E CAMPO {assim} COM PREFIXO vão com hífen (ku-Syden, ku-{comunidade}): o prefixo
// do zulu se cola à palavra, e colado a um nome que a tela ainda não conhece ele viraria uma palavra só.
//
// O DETECTOR DO TESTE DE IDIOMAS: latino sem acento nenhum — vai o das chaves, como toda língua latina.
//
// VOCABULÁRIO, decidido uma vez: comunidade = umphakathi, canal = isiteshi, sala de voz = igumbi
// lezwi, chamada = ikholi, conversa = ingxoxo, mensagem = umlayezo, senha = iphasiwedi, lixeira =
// umgqomo, tópico = uchungechunge, conta = i-akhawunti, administrador = umphathi, dono = umnikazi,
// cargo = indima, convite = isimemo, perfil = iphrofayela, transmissão = ukusakaza, tela = isikrini,
// membro = ilungu, pacote = iphakethe, enquete = inhlolovo, denúncia = umbiko, vila = isigodi,
// guarda-roupa = ikhabethe, cutucada = ukugqugquzela, recado (da tela de boas-vindas e do aviso) =
// isaziso.
//
// SOM E VOZ SÃO DUAS PALAVRAS: izwi é a voz, umsindo é o som de soundboard e de aviso.
//
// SELO E INSÍGNIA SEPARADOS: selo = uphawu (o da comunidade), insígnia = ibheji (a da pessoa).

