    'Faka i-imeyili ye-akhawunti yakho bese sikuthumelela isixhumanisi sokukhetha enye.',
  'Digite sua senha para confirmar': 'Thayipha iphasiwedi yakho ukuze uqinisekise',
  'Disponível': 'Ukhona',
  'Do laranja ao vermelho, como carvão aceso.': 'Kusuka ewolintshi kuya kokubomvu, njengamalahle avuthayo.',
  'Dois emojis com o mesmo nome: cada um precisa do seu.': 'Ama-emoji amabili anegama elifanayo: ngayinye idinga elayo.',
  'Dono': 'Umnikazi',
  'Dono da comunidade': 'Umnikazi womphakathi',
  'Dourado com brilho que passa devagar.': 'Okwegolide okunokukhazimula okudlula kancane.',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.':
    'Phakathi nekholi, le nkinobho idlalela bonke abasegumbini le misindo. Faka amaphakethe asenziwe noma ulayishe eyakho; ozithandayo zihlala phambili kuphaneli.',
  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.':
    'Yinto yokuqala umuntu ayibonayo lapho engena emphakathini, kanye kuphela. Ngaphandle kwalokhu, ungena ngqo ohlwini leziteshi.',
  'É assim que os outros veem você na lista e nas conversas.': 'Yileyo ndlela abanye abakubona ngayo ohlwini nasezingxoxweni.',
  'é o que você está enviando': 'yilokho okuthumelayo',
  'É o seu único jeito de entrar. Defina uma senha antes de desligar.': 'Yiyo kuphela indlela yakho yokungena. Setha iphasiwedi ngaphambi kokunqamula.',
  'E-mail': 'I-imeyili',
  'Eco de lugar grande e vazio.': 'Ukunanela kwendawo enkulu engenalutho.',
  'Efeito do nome': 'Umphumela wegama',
  'Efeito para a sala': 'Umphumela wegumbi',
  'Efeitos visuais na chamada': 'Imiphumela ebonakalayo ekholini',
  'Em branco: fica até você apagar.': 'Kungenalutho: kuhlala uze ukususe.',
  'Em branco: já.': 'Kungenalutho: manje.',
  'Em uso': 'Kuyasetshenziswa',
  'Emojis': 'Ama-emoji',
  'Emojis da comunidade': 'Ama-emoji omphakathi',
  'Encerrar a apresentação': 'Qeda isethulo',
  'Endereço': 'Ikheli',
  'Endereço guardado. Confira a sua caixa de entrada para confirmar.': 'Ikheli ligciniwe. Hlola ibhokisi lakho lokungenayo ukuze uqinisekise.',
  'Endereço guardado. O envio de e-mail ainda não está ligado neste servidor, então o link de confirmação ficou no registro do servidor.':
    'Ikheli ligciniwe. Ukuthunyelwa kwama-imeyili akukavulwa kule seva, ngakho isixhumanisi sokuqinisekisa sisele kurekhodi leseva.',
  'Enfeites, sons e emojis': 'Imihlobiso, imisindo nama-emoji',
  'Enquanto isto aparecer, os números abaixo não existem —': 'Uma nje lokhu kusabonakala, izinombolo ezingezansi azikho —',
