  'Online agora: {n}': 'Ku-inthanethi manje: {n}',
  'Os números aparecem no alto da lista de canais, para todo mundo, e mudam sozinhos.': 'Izinombolo zivela phezulu ohlwini lweziteshi kuwo wonke umuntu, futhi ziziguqulela ngokwazo.',
  'Criar uma sala para cada pessoa que entrar': 'Dala igumbi kuwo wonke ongenayo',
  'Entre para criar a sua sala': 'Ngena ukuze udale igumbi lakho',
  'Limite de pessoas': 'Umkhawulo wabantu',
  'Quantas pessoas cabem (0 = sem limite)': 'Bangaki abangangena (0 = awukho umkhawulo)',
  'Canal de destaques': 'Isiteshi sokugqamile',
  'Destaques': 'Okugqamile',
  'Estrelas necessárias': 'Izinkanyezi ezidingekayo',
  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'Uma umlayezo uqoqa izinkanyezi ⭐ ezanele, i-Syden iwuthumela esiteshini sokugqamile. Inkanyezi yalowo owubhalile ayibalwa, futhi ukususa umlayezo kususa nokugqamile.',
  '🎉 Resultado do sorteio de {premio}: {vencedores}. Parabéns!': '🎉 Umphumela womncintiswano we-{premio}: {vencedores}. Halala!',
  '🎉 Sorteio: {premio}! Reaja com 🎉 para participar. O resultado sai em {quando}.': '🎉 Umncintiswano: {premio}! Phendula ngo-🎉 ukuze ubambe iqhaza. Umphumela uzophuma ngo-{quando}.',
  'Começar o sorteio': 'Qala umncintiswano',
  'Encerrar agora': 'Qeda manje',
  'Ganhadores': 'Inani lemiklomelo',
  'Ninguém participou.': 'Akekho obambe iqhaza.',
  'Novo sorteio': 'Umncintiswano omusha',
  'O sorteio de {premio} terminou sem participantes.': 'Umncintiswano we-{premio} uphele ngaphandle kwabahlanganyeli.',
  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'I-Syden imemezela umklomelo esiteshini, futhi ofuna ukubamba iqhaza uphendula ngo-🎉. Ngesikhathi esibekiwe, ikhetha phakathi kwabaphendulile bese ithumela umphumela.',
  'Participantes: {n}': 'Abahlanganyeli: {n}',
  'Prêmio': 'Umklomelo',
  'Quem ganhou: {nomes}': 'Uwinile: {nomes}',
  'Sortear de novo': 'Khetha futhi',
  'Sorteios': 'Imincintiswano',
  'Termina em': 'Iphela',
  'Termina em {quando}': 'Iphela ngo-{quando}',
  'Terminou em {quando}': 'Iphele ngo-{quando}',
  'Aniversário': 'Usuku lokuzalwa',
  'Aniversários': 'Izinsuku zokuzalwa',
  'Canal dos parabéns': 'Isiteshi semikhonzo',
  'Dia': 'Usuku',
  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'Namuhla wusuku lokuzalwa luka-{pessoa}! 🎉 Usuku oluhle lokuzalwa!',
  'Mês': 'Inyanga',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'Ngosuku lokuzalwa lwalowo ofake usuku lwakhe, i-Syden ithumela umkhonzo esiteshini esikhethiwe. Sebenzisa u-{pessoa} esikhundleni segama.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'Usuku nenyanga kuphela, akukaze kube unyaka. Imiphakathi ememezela izinsuku zokuzalwa ihalalisela ngalolo suku. Akuphoqelekile, futhi ungakususa noma nini.',
  'Texto dos parabéns': 'Umbhalo womkhonzo',
  'Agendar': 'Hlela isikhathi',
  'Apagar a mensagem agendada': 'Susa umlayezo ohleliwe',
  'Canal': 'Isiteshi',
  'Combinado: lembro você em {tempo}.': 'Kulungile: ngizokukhumbuza ngemva kuka-{tempo}.',
  'Lembrar de mim': 'Ngikhumbuze',
  'Lembrar de mim em…': 'Ngikhumbuze ngemva kuka…',
  'Lembrete': 'Isikhumbuzo',
  'Lembrete — {autor}: {trecho}': 'Isikhumbuzo — {autor}: {trecho}',
  'Mensagens agendadas': 'Imilayezo ehleliwe',
  'Na hora marcada, o Syden publica o texto no canal. Dá para repetir todo dia ou toda semana.': 'Ngesikhathi esibekiwe, i-Syden ithumela umbhalo esiteshini. Ingaphindwa nsuku zonke noma maviki onke.',
  'Nova mensagem agendada': 'Umlayezo omusha ohleliwe',
  'O que o Syden publica': 'Lokho i-Syden ekuthumelayo',
  'Quando': 'Nini',
  'Repetir': 'Phinda',
  'Texto da mensagem agendada': 'Umbhalo womlayezo ohleliwe',
  'Toda semana': 'Maviki onke',
  'Todo dia': 'Nsuku zonke',
  'Uma vez': 'Kanye',
  'Alguém escreve o comando no começo de uma mensagem, como !regras, e o Syden responde no canal com o texto que você cadastrar. Use {pessoa} para o nome de quem pediu e {comunidade} para o nome da comunidade.': 'Umuntu ubhala umyalo ekuqaleni komlayezo, njenge-!regras, bese i-Syden iphendula esiteshini ngombhalo owufakile. Sebenzisa u-{pessoa} egameni lalowo ocelile no-{comunidade} egameni lomphakathi.',
  'Apagar o comando {comando}': 'Susa umyalo {comando}',
