  'Em silêncio até {hora}': 'Ekuthuleni kuze kube ngu-{hora}',
  'Escolha o tempo': 'Khetha isikhathi',
  'Motivo da advertência': 'Isizathu sesixwayiso',
  'Seu silêncio em {comunidade} acabou.': 'Ukuthula kwakho ku-{comunidade} kuphelile.',
  'Silenciar {pessoa} por': 'Ukuthula kuka-{pessoa} isikhathi',
