  'Modo lento: uma mensagem a cada {tempo}.': 'Imodi ehamba kancane: umlayezo owodwa njalo ngemizuzwana {tempo}.',
  'Palavras proibidas': 'Amagama avinjelwe',
  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'Isikhathi umuntu ngamunye alinda ngaso phakathi kwemilayezo esiteshini.',
  'Regras': 'Imithetho',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'Imithetho i-Syden eyisebenzisa ngokwayo, ngaphambi kokuthi umlayezo uvele. Ayisebenzi kubaphathi. Umlayezo ovinjiwe ubuyela kulowo owubhalile, nesizathu, futhi akekho omunye owubonayo.',
  'Salvo.': 'Kulondoloziwe.',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'Elilodwa emgqeni ngamunye. Kubalwa igama lonke, ngaphandle komehluko wezimpawu noma wezinhlamvu ezinkulu: ukuvimbela igama akuvimbi igama elide elimane liliqukethe.',
  '{faltam} pontos para o nível {proximo}.': 'Amaphuzu angu-{faltam} ukuya ezingeni {proximo}.',
  'Adicionar recompensa': 'Engeza umklomelo',
  'Cada mensagem vale pontos (uma por minuto), e cada minuto numa sala com mais alguém também. Quem sobe de nível recebe um aviso só para si.': 'Umlayezo ngamunye unamaphuzu (owodwa ngomzuzu), kanjalo nomzuzu ngamunye egumbini nomunye umuntu. Okhuphuka izinga uthola isaziso esingesakhe kuphela.',
  'Cargo da recompensa': 'Indima yomklomelo',
  'Crie um cargo acima para usar como recompensa.': 'Dala indima ngenhla ukuze uyisebenzise njengomklomelo.',
  'Escolha o cargo': 'Khetha indima',
  'Níveis': 'Amazinga',
  'Níveis e ranking ligados': 'Amazinga nohlu lwezikhundla kuvuliwe',
  'Nível {nivel}': 'Izinga {nivel}',
