  'Ranking': 'Uhlu lwezikhundla',
  'Recompensas': 'Imiklomelo',
  'Tirar a recompensa do nível {nivel}': 'Susa umklomelo wezinga {nivel}',
  'Você ainda não tem pontos aqui. Converse ou entre numa sala com alguém.': 'Awukabi namaphuzu lapha. Xoxa noma ungene egumbini nomuntu.',
