  'Apagar o cargo {cargo}': 'Susa indima {cargo}',
  'Cargos': 'Izindima',
  'Cargos dão nome e cor a grupos de pessoas: "Veterano", "Turma da raide". Não mudam o que cada um pode fazer na comunidade.': 'Izindima zinika amaqembu abantu igama nombala: "Unomakhelwane omdala", "Iqembu lokuhlasela". Azishintshi lokho okwenziwa nguwonke-wonke emphakathini.',
  'Cor do cargo {cargo}': 'Umbala wendima {cargo}',
