  'Paleta de cores': 'Iqoqo lemibala',
  'Syden': 'Syden',
  'Azul-noite, creme e âmbar: a cara do app.': 'Okuluhlaza kwasebusuku, ukhilimu kanye no-amber: ukubukeka kohlelo uqobo.',
  'Clássica': 'Okwakudala',
  'Cinza e azul, a de antes do coelho novo.': 'Okumpunga nokuluhlaza, okwangaphambi konogwaja omusha.',
  'Grafite': 'Igrafayithi',
  'Cinza neutro, quase preto, com verde-água.': 'Okumpunga okungathathi hlangothi, cishe okumnyama, nokuluhlaza kolwandle.',
  'Alto contraste': 'Umehluko ophezulu',
  'Preto, branco e amarelo, para ler sem esforço.': 'Okumnyama, okumhlophe nokuphuzi, kulula ukufunda.',
  'A paleta vale no tema escuro. Com o sol ligado, o Syden usa o tema claro.': 'Iqoqo lemibala lisebenza endikimbeni emnyama. Uma ilanga livuliwe, i-Syden isebenzisa indikimba ekhanyayo.',
  'Não deu para entrar agora. Tente de novo.': 'Akukwazekanga ukungena manje. Zama futhi.',
  'Seu nome': 'Igama lakho',
  'Entrando…': 'Iyangena…',
  'Ao entrar, você concorda com os termos de uso.': 'Ngokungena, uyavuma imigomo yokusebenzisa.',
