    'Indawo entsha, eneziteshi zayo. Ukhetha ongenayo ngekhodi yesimemo.',
  'Um pacote instalado entra para toda a comunidade: os emojis dele passam a valer nas mensagens de todo mundo.':
    'Iphakethe elifakiwe lingena kuwo wonke umphakathi: ama-emoji alo aqala ukusebenza emilayezweni yawo wonke umuntu.',
  'Uma cópia do que você escreveu fica 90 dias fora do app, para o caso de pedido de autoridade. Ninguém a lê pelo Syden.':
    'Ikhophi yalokho okubhalile ihlala izinsuku ezingu-90 ngaphandle kohlelo, uma kwenzeka kuba nesicelo seziphathimandla. Akekho oyifundayo nge-Syden.',
