  'Sudoku': 'Sudoku',
  'Todo mundo recebe o mesmo sudoku, e a sala vê quem está mais perto de terminar.': 'Wonke umuntu uthola i-sudoku efanayo, futhi igumbi libona ukuthi ubani oseduze nokuqeda.',
  'Cinco em linha': 'Ezinhlanu emgqeni',
  'Duas pessoas põem pedras no tabuleiro, uma de cada vez. Vence quem fizer cinco seguidas. A sala assiste.': 'Abantu ababili babeka amatshe ebhodini ngokushintshana. Uyawina owenza ezinhlanu zilandelana. Igumbi liyabukela.',
