  'Entre na sala de voz para jogar com a turma.': 'Ngena egumbini lezwi ukuze udlale nabangane.',
  'Já tem uma partida acontecendo nesta sala.': 'Sekuvele kunomdlalo oqhubekayo kuleli gumbi.',
  'Só quem começou a partida pode encerrá-la antes do fim.': 'Nguye kuphela owaqala umdlalo ongawuqeda ngaphambi kokuphela.',
  'Lobisomem': 'Umuntu-mpisi',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Ebusuku, khetha nabanye abantu-mpisi ukuthi nizohlasela bani. Emini, ungavumeli muntu asole.',
  'Vidente': 'Umboni',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Ebusuku, thola ukuthi othile ungumuntu-mpisi yini. Kusho emini, uma ucabanga ukuthi kufanele ingozi.',
  'Anjo': 'Ingelosi',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Ebusuku, khetha umuntu ozomvikela. Uma abantu-mpisi behlasela lowo muntu, uyasinda.',
  'Da vila': 'Owasesigodini',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Ebusuku, lala. Emini, thola ukuthi obani abantu-mpisi bese uvota ukuze baphume emdlalweni.',
  'A vila venceu!': 'Isigodi siwinile!',
  'Os lobisomens venceram!': 'Abantu-mpisi bawinile!',
  'Noite {n}. A vila dorme.': 'Ubusuku {n}. Isigodi silele.',
  'Os lobisomens atacaram {nome} durante a noite.': 'Ebusuku abantu-mpisi bahlasele u-{nome}.',
  'Ninguém morreu esta noite.': 'Akekho oshonile kulobu busuku.',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': 'Usuku {n}. Xoxani bese nivotela lowo enicabanga ukuthi ungumuntu-mpisi.',
  'A vila tirou {nome} do jogo.': 'Isigodi sikhiphe u-{nome} emdlalweni.',
  'Empate: ninguém sai hoje.': 'Kulingene: akekho ophumayo namuhla.',
  'Clique em quem os lobisomens vão atacar.': 'Chofoza lowo abantu-mpisi abazomhlasela.',
  'Você já usou a sua visão esta noite.': 'Usuwusebenzisile umbono wakho walobu busuku.',
  'Clique em alguém para descobrir se é lobisomem.': 'Chofoza othile ukuze uthole ukuthi ungumuntu-mpisi yini.',
  'Clique em quem você quer proteger esta noite.': 'Chofoza lowo ofuna ukumvikela kulobu busuku.',
  'Durma. Os outros papéis estão agindo.': 'Lala. Ezinye izindima ziyasebenza.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'Usuphumile emdlalweni. Manje buka nje — ungasho lutho!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'Chofoza lowo ofuna ukumkhipha emdlalweni. Onamavoti amaningi uyaphuma; uma kulingene, akekho.',
