  'não é lobisomem': 'akayena umuntu-mpisi',
  'Ninguém hoje': 'Akekho namuhla',
  'A solução do problema.': 'Isixazululo senkinga.',
  'Acertou! Agora é torcer pelos outros.': 'Kulungile! Manje khuthaza abanye.',
  'Esse não era o lance. Espere a solução.': 'Lokho bekungesona isinyathelo. Linda isixazululo.',
  'Você joga com as brancas. Ache o melhor lance.': 'Udlala ngabamhlophe. Thola isinyathelo esingcono kakhulu.',
  'Você joga com as pretas. Ache o melhor lance.': 'Udlala ngabamnyama. Thola isinyathelo esingcono kakhulu.',
  'Ver este problema no Lichess': 'Bona le nkinga ku-Lichess',
  'Problema do Lichess · nota {nota}': 'Inkinga ye-Lichess · izinga {nota}',
  'Cada um recebe um papel em segredo. À noite os lobisomens atacam; de dia a vila conversa e vota em quem tirar do jogo. Precisa de 4 pessoas ou mais.': 'Wonke umuntu uthola indima ngasese. Ebusuku abantu-mpisi bayahlasela; emini isigodi siyaxoxa bese sivota ukuthi ubani ophuma emdlalweni. Kudingeka abantu abangu-4 noma ngaphezulu.',
  'Problemas de xadrez': 'Izinkinga ze-chess',
  'Todo mundo recebe o mesmo problema do Lichess. Quem achar o lance certo mais rápido ganha o ponto extra.': 'Wonke umuntu uthola inkinga efanayo ye-Lichess. Othola isinyathelo esifanele ngokushesha uthola iphuzu elengeziwe.',
  'Os problemas de xadrez não estão no servidor.': 'Izinkinga ze-chess azikho kuseva.',
  'Este problema já acabou.': 'Le nkinga isiphelile.',
  'Lance inválido.': 'Isinyathelo esingavumelekile.',
  'Solo': 'Wedwa',
  'Coletivo': 'Ndawonye',
  'Palavra secreta': 'Igama eliyimfihlo',
  'Todo mundo tenta adivinhar a mesma palavra de 5 letras, em 6 chutes. A sala vê as cores dos outros, mas não as letras. Quem acertar com menos chutes ganha mais pontos.': 'Wonke umuntu uzama ukuqagela igama elifanayo elinezinhlamvu ezi-5, ngemizamo emi-6. Ubona imibala yabanye, kodwa hhayi izinhlamvu zabo. Oqagela ngemizamo embalwa uthola amaphuzu amaningi.',
  'A palavra era: {palavra}': 'Igama belithi: {palavra}',
  'Acabaram os seus chutes. Espere a palavra.': 'Imizamo yakho iphelile. Linda igama.',
