  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'Qala ngokwakha izindima zomphakathi, ku-Amalungu. Bese ubuyela lapha ukuze zinikezwe ngokuzenzakalelayo.',
