  'Cargos por reação': 'Izindima ngokusabela',
  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'I-Syden ithumela umlayezo esiteshini one-emoji eyodwa endimeni ngayinye. Osabelayo uthola indima; osusa ukusabela kwakhe uyayilahlekelwa.',
