  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}): kususiwe ku-Syden ngoba u-{quem} uthi unamalungelo. Uma ubunemvume yokushicilela, phendula lapha uchaze: impendulo yakho izocatshangelwa. Kuze kucace lokhu, kuhlala kususiwe. Imigomo ichaza ukuthi kusebenza kanjani, esigabeni 4: https://syden.chat/termos.html#direito-autoral',
