  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': 'Onelungelo ubhalela ku-direitos@syden.chat echaza ukuthi kuyini nokuthi kukuphi. Sesha ngegama, susa, futhi owalayisha uzothola isaziso engxoxweni nawe, lapho angaphikisa khona.',
