  'Quem precisa falar com a administração abre um ticket no início da comunidade, com um assunto. Ele vira uma conversa privada em grupo entre essa pessoa e quem administra, e aparece na lista de conversas de vocês.': 'Ofuna ukukhuluma nabaphathi uvula ithikithi ekuqaleni komphakathi, enesihloko. Liba yingxoxo yeqembu eyimfihlo phakathi kwalowo muntu nabaphathi, futhi livela ohlwini lwenu lwezingxoxo.',
