  'Mensagem': 'Umlayezo',
  'Motivo:': 'Isizathu:',
  'Na conta dele, em Configurações → Família, aparece um código. Digite aqui.': 'Ku-akhawunti yakhe, ku-Izilungiselelo → Umndeni, kuvela ikhodi. Yibhale lapha.',
