  'nos últimos 7 dias: {tempo}': 'ezinsukwini ezingu-7 ezedlule: {tempo}',
  'O limite combinado com o seu responsável é de {n} minutos por dia. Amanhã, o Syden abre de novo.': 'Umkhawulo ovumelene ngawo nomnakekeli wakho yimizuzu engu-{n} ngosuku. Kusasa, i-Syden izovuleka futhi.',
  'O motivo (a pessoa vai ler)': 'Isizathu (umuntu uzosifunda)',
  'O seu recurso foi recebido em {quando}. Quem cuida do Syden vai ler e responder.': 'Isicelo sakho samukelwe ngo-{quando}. Abanakekela i-Syden bazosifunda baphendule.',
  'O seu responsável': 'Umnakekeli wakho',
  'O seu tempo de hoje acabou': 'Isikhathi sakho sanamuhla siphelile',
  'O Syden é para quem tem 13 anos ou mais.': 'I-Syden ingeyabantu abaneminyaka engu-13 noma ngaphezulu.',
  'O Syden é para quem tem 13 anos ou mais. Ninguém vê a sua data.': 'I-Syden ingeyabantu abaneminyaka engu-13 noma ngaphezulu. Akekho obona usuku lwakho.',
  'O Syden passou a pedir a idade de todo mundo, para proteger quem tem menos de 18 anos (a lei do ECA Digital). Ninguém vê a sua data: só a faixa de idade é usada.': 'I-Syden manje ibuza iminyaka yawo wonke umuntu, ukuze ivikele abangaphansi kweminyaka engu-18 (umthetho we-ECA Digital). Akekho obona usuku lwakho: kusetshenziswa iqembu leminyaka kuphela.',
  'Para quem foi comunicado e o protocolo (ex.: SaferNet 123)': 'Kubikwe kubani kanye nenombolo yecala (isib.: SaferNet 123)',
  'Por segurança, a prévia das transmissões fica fechada para menores de idade.': 'Ngokuphepha, ukubuka kuqala kokusakaza kuvaliwe kwabangaphansi kweminyaka engu-18.',
  'Por segurança, menores de idade conversam no particular só com amigos.': 'Ngokuphepha, abangaphansi kweminyaka engu-18 baxoxa ngasese nabangane kuphela.',
  'Qual é a sua data de nascimento?': 'Lithini usuku lwakho lokuzalwa?',
  'Quem muda estas regras é o seu responsável.': 'Oshintsha le mithetho ngumnakekeli wakho.',
  'Quem tem de 13 a 15 anos usa o Syden com a conta ligada à de um pai, mãe ou responsável. É a lei (ECA Digital), e é para a sua segurança.': 'Abaneminyaka engu-13 kuya ku-15 basebenzisa i-Syden ne-akhawunti exhunywe neyobaba, umama noma umnakekeli. Kungumthetho (ECA Digital), futhi kungokuphepha kwakho.',
  'Quem tem menos de 18 anos usa o Syden com proteções a mais, e de 13 a 15 anos com a conta ligada à de um responsável (a lei do ECA Digital).': 'Abangaphansi kweminyaka engu-18 basebenzisa i-Syden nezivikelo ezengeziwe, kuthi abaneminyaka engu-13 kuya ku-15 basebenzise i-akhawunti exhunywe neyomnakekeli (umthetho we-ECA Digital).',
  'Recorrer da decisão': 'Cela ukubuyekezwa kwesinqumo',
  'Recurso em {quando}:': 'Isicelo ngo-{quando}:',
  'Registrar a comunicação': 'Bhalisa umbiko',
  'Só contas de menores de idade se ligam a um responsável.': 'Ama-akhawunti abangaphansi kweminyaka engu-18 kuphela axhunywa nomnakekeli.',
  'Só um adulto pode ser o responsável por outra conta.': 'Umuntu omdala kuphela ongaba umnakekeli we-akhawunti yomunye.',
  'Sua conta tem uma pendência. Abra o Syden de novo para ver o que fazer.': 'I-akhawunti yakho inento elindile. Vula i-Syden futhi ukuze ubone okufanele ukwenze.',
