  'Turbo (da segunda volta em diante)': 'I-turbo (kusukela emzuliswaneni wesibili)',
  '{n} voltas': 'Imizuliswano: {n}',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'Amandla ayimpilo ne-turbo: ukushayisa umphetho kuyawasebenzisa, umugqa obomvana uyawagcwalisa futhi.',
  'A nave explodiu: a energia acabou.': 'Umkhumbi uqhumile: amandla aphelile.',
  'Posição: {posicao} de {total}': 'Isikhundla: {posicao} kwabangu-{total}',
  'Escolher a pista': 'Khetha umzila',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Umjaho wemikhumbi eyizaqathi emzileni olengayo, ushesha kakhulu kune-kart. Amandla ayimpilo ne-turbo: ukushayisa umphetho kuyawasebenzisa, umugqa obomvana uyawagcwalisa futhi, futhi ukuphuma emzileni kusho ukuwa. Wedwa: ubhekene newashi nezipoki zabangane.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'Ama-kart enkundleni evaliwe, ngalinye linamabhaluni amathathu. Thatha amabhokisi usebenzise izinto ukuqhumisa amabhaluni abanye: ophelelwa amabhaluni uyaphuma, kunqobe osala ekugcineni.',
  'Esquadrilha da toca': 'Iqembu Lezindiza Lomgodi',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Izindiza ezincane zesanqante zilwa nezinambuzane zengadi: gwema imbewu, thatha ukuqiniswa bese uwisa isithombe sokwesabisa izinyoni somshini ekugcineni. Iqembu lindiza emagagasini afanayo, futhi amaphuzu eqembu ayahlanganiswa.',
  'O espantalho caiu!': 'Isithombe sokwesabisa siwile!',
  'A praga venceu desta vez.': 'Izinambuzane ziwinile kulokhu.',
