  'Você desistiu.': 'Unikezele.',
  'O tempo acabou: ganhou quem tinha mais.': 'Isikhathi siphelile: owayenokuningi uwinile.',
  'A sua Maravilha ficou de pé por 2 minutos.': 'Isimangaliso sakho simile imizuzu engu-2.',
  'A Maravilha do computador ficou de pé por 2 minutos.': 'Isimangaliso sekhompyutha simile imizuzu engu-2.',
