  'Este jogo não se joga na sala.': 'Lo mdlalo awudlalwa egumbini.',
  'Ponha os seus navios no mar.': 'Beka imikhumbi yakho olwandle.',
  'Esperando {nome} pôr os navios…': 'Kulindwe u-{nome} ukuthi abeke imikhumbi…',
