  'Seus navios': 'Imikhumbi yakho',
  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'Khetha umkhumbi bese uthinta ulwandle. Donsa ukuze uwususe.',
  'Sortear a frota': 'Imikhumbi engahleliwe',
  'Sua frota já está pronta.': 'Imikhumbi yakho isilungile.',
  'Ponha todos os navios antes.': 'Qala ubeke yonke imikhumbi.',
  'Escolha um navio.': 'Khetha umkhumbi.',
  'O navio não cabe aí.': 'Umkhumbi awungeni lapho.',
  'Os navios não podem encostar um no outro.': 'Imikhumbi ayikwazi ukuthintana.',
  'Minigolfe 3D': 'I-minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Imigodi eyisishiyagalombili ku-3D, enemithambeka, inqaba nomshini womoya, bonke badlala umgodi ofanayo ngesikhathi esisodwa. Donsa ukuze ukhombe futhi unikeze amandla, bese uyeka. Uwina onemishayo emincane kakhulu isiyonke.',
  'Ver o buraco de cima': 'Buka umgodi usuka phezulu',
  'Fora da pista! Mais uma tacada.': 'Ngaphandle komzila! Ukushaya okukodwa okwengeziwe.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Donsa eceleni ukuze ukhombe naphansi ukuze uthole amandla, bese uyeka. Ngekhibhodi: imicibisholo iyakhomba, futhi i-Space obambe kuyo inika amandla.',
  'Futebol dos coelhos': 'Ibhola Lezinogwaja',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Ibhola lezinyawo enkundleni encane, libukwa phezulu. Thinta ibhola ukuze ulihole, bamba i-Space ukuze ukhahlele kakhulu, bese uqhubela nge-X. Egumbini, amaqembu agcwaliswa ngamarobhothi.',
  'Quantos por time?': 'Bangaki eqenjini ngalinye?',
  'Seu time venceu!': 'Iqembu lakho liwinile!',
  'Seu time perdeu.': 'Iqembu lakho lihlulekile.',
  'Passe': 'Dlulisa',
  'Chutar': 'Khahlela',
  'Chutar (segure para mais força)': 'Khahlela (bamba ukuze uthole amandla amaningi)',
  'Gol!': 'Igoli!',
  'Gol contra': 'Igoli lokuzifaka',
  'Partida inválida.': 'Umdlalo ongavumelekile.',
  'Ninguém para jogar.': 'Akekho ozodlala.',
  'Caça às pragas da horta': 'Ukuzingela izinambuzane zengadi',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Amagwababa nezintethe zihlasela ingadi. Khomba bese uchofoza ukuze uzishaye ngaphambi kokuthi zibaleke: izinhlamvu zibaliwe, futhi igagasi ngalinye lifika ngokushesha. Owenza amaphuzu amaningi uyawina.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Khomba bese uchofoza izinambuzane ngaphambi kokuthi zibaleke. Ukudubula ngakunye kusebenzisa isanqante esisodwa.',
