  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Donsela ibhola emuva bese uliyeka. Ngekhibhodi: imicibisholo iyakhomba, futhi i-Space obambe kuyo inika amandla.',
