  'Para a direita': 'Ngakwesokudla',
  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Imicibisholo ukuze ugijime, i-Space ukuze ugxume (yibambe ukuze uye phezulu kakhulu).',
  'Nenhum amigo jogou esta fase ainda.': 'Akukho mngane osedlale lesi sigaba.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'Imvula engadini: wonke umuntu uthola izanqante ezingu-{n}.',
  '{nome} achou {n} cenouras escondidas.': 'U-{nome} uthole izanqante ezifihliwe ezingu-{n}.',
  '{nome} trocou de lugar com {outro}.': 'U-{nome} ushintshe izindawo no-{outro}.',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'Kushode abantu: umdlalo uphele ngaphambi kokuphela, ngaphandle kwezindebe.',
  'Saiu antes do fim': 'Uphume ngaphambi kokuphela',
  'Jogar o dado': 'Phonsa idayisi',
  '{nome} comprou a cenoura dourada!': 'U-{nome} uthenge isanqante segolide!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Uthenga isanqante segolide ngezanqante ezingu-{preco}?',
  'Comprar': 'Thenga',
  '{nome} chegou à cenoura dourada.': 'U-{nome} ufike esanqanteni segolide.',
  'Quantas rodadas?': 'Imizuliswano emingaki?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Onogwaja bavikela ingadi ezimpungushe, kumagwababa nasensele. Hambani ndawonye, shayani ngama-combo futhi ninakekelane: abantu abangu-1 kuya ku-4.',
  'Pulo do coelho': 'Ukugxuma Kukanogwaja',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Umjaho wezinkundla: gijima, gxuma futhi ungawi. Uwedwa, ubhekene nesikhathi nezipoki zabangane; neqembu, bukhoma, esigabeni esisodwa noma kuzo zontathu.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Shintsha imifino emibili engomakhelwane ukuze uqoqe emithathu noma ngaphezulu efanayo. Inqwaba ikhuphuka ingami: ungayivumeli ifinyelele phezulu. Neqembu, amaketango nama-combo athumela amabhokisi kwabanye.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Imigodi eyisithupha ye-minigolf, wonke umuntu udlala ofanayo ngesikhathi esisodwa. Donsela ibhola emuva bese uliyeka ukuze ushaye. Uwina onokushaya okumbalwa kakhulu kukonke.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Wonke umuntu uphonsa idayisi ngesikhathi sakhe futhi ahambe engadini. Qoqa izanqante ukuze uthenge isanqante segolide, futhi ngemva komzuliswano ngamunye iqembu lidlala umdlalo omncane. Uwina onezanqante zegolide eziningi kakhulu.',
  'Os pódios e as conquistas da turma': 'Izinkundla zabanqobi nempumelelo yeqembu',
  'Visitar o quarto': 'Vakashela igumbi',
  'Quem visita o seu quarto': 'Ubani ongavakashela igumbi lakho',
  'Todo mundo': 'Wonke umuntu',
  'Seus amigos': 'Abangane bakho',
  'Só quem você convidar': 'Labo obamemayo kuphela',
  'Qualquer conta pode entrar e ver os troféus em destaque.': 'Noma iyiphi i-akhawunti ingangena ibone izindebe ezigqanyisiwe.',
  'Seus amigos podem entrar e ver os troféus em destaque.': 'Abangane bakho bangangena babone izindebe ezigqanyisiwe.',
  'Nem os amigos entram, só quem você marcar aqui.': 'Ngisho nabangane abangeni, kuphela labo obamaka lapha.',
  'Você ainda não tem amigos para convidar.': 'Awukabi nabangane ongabamema.',
