  'Você saiu da sala, e a partida continuou sem você.': 'Uphume egumbini, futhi umdlalo uqhubekile ngaphandle kwakho.',
  'Menos de duas pessoas ficaram até o fim: desta vez, sem pódio.': 'Abantu abangaphansi kwababili basala kwaze kwaba sekupheleni: kulokhu, ayikho inkundla yabawinile.',
