  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Hamba ezinhloko-dolobha zaseBrazil, uthenge amadolobha futhi uqoqe irenti kulabo abama kuwo. Uma unesifunda sonke, ungakha izakhiwo. Shintshana, uqhudelane ezindalini futhi ungaphelelwa yimali.',
