  'O fundo não é de uma cor só, e ficou como veio.': 'Ingemuva akuwona umbala owodwa, ngakho ishiywe injengoba injalo.',
  'No app do Syden, o recorte funciona com qualquer fundo.': 'Ku-app ye-Syden, noma iyiphi ingemuva ingasuswa.',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'Ukususa ngemodeli kuhlulekile, ngakho kusetshenziswe indlela elula.',
  'Mandar figurinha': 'Thumela isitikha',
  'Tirar figurinha': 'Susa isitikha',
  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.': 'Dala izitikha ngezithombe zakho, noma ulondoloze lezo ozithola engxoxweni.',
  'Dominó': 'Idomino',
  'Truco': 'Truco',
  'Damas': 'I-Drafts',
  'Batalha naval': 'Impi yasolwandle',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Idomino elijwayelekile, labantu abangu-2 kuya ku-4 (uma bebane, ngababili). Hlanganisa amatshe emikhawulweni, futhi oqeda kuqala uthola amaphuzu asezandleni zabanye.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'I-truco yaseBrazil, enekhadi elivuliwe ne-manilha, yabantu abangu-2 noma amaqembu ababili kwabangu-4. Cela i-truco, ukhuphule uye kwisithupha, kwisishiyagalolunye nakweyishumi nambili, noma ubaleke. Uwina ofinyelela amaphuzu angu-12.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'I-Drafts yaseBrazil: ukudla kuyimpoqo, phambili nangemuva, futhi inkosi ihamba umugqa oxiyelelayo wonke. Igumbi liyabukela.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Ngamunye ufihla imikhumbi yakhe bese edubula olwandle lomunye. Uma ushayile, dubula futhi. Uwina ocwilisa yonke imikhumbi kuqala. Igumbi liyabukela.',
