  'Não há mão de onze agora.': 'Asikho isandla seshumi nanye manje.',
  'Quem decide a mão de onze é quem tem 11.': 'Onquma ngesandla seshumi nanye yilowo onamaphuzu angu-11.',
  'Não há pedido de truco agora.': 'Asikho isicelo se-truco manje.',
  'Quem responde é o outro lado.': 'Ophendulayo uhlangothi olunye.',
  'Não dá para aumentar mais.': 'Akusenakwenyuswa.',
  'Espere a resposta do truco.': 'Linda impendulo ye-truco.',
  'Agora não dá para pedir truco.': 'Manje awukwazi ukucela i-truco.',
  'Essa carta não está na sua mão.': 'Lelo khadi alikho esandleni sakho.',
  'A carta coberta só vale da segunda rodada em diante.': 'Ikhadi elimboziwe livunyelwe kusukela emzuliswaneni wesibili kuphela.',
  'Espere a próxima mão.': 'Linda isandla esilandelayo.',
  'Você tem uma pedra que serve.': 'Unetshe elifanelekayo.',
  'Não há pedras para comprar.': 'Awekho amatshe okuthatha.',
  'Compre uma pedra antes de passar.': 'Thatha itshe ngaphambi kokudlula.',
  'Essa pedra não está na sua mão.': 'Lelo tshe alikho esandleni sakho.',
  'A primeira pedra é outra.': 'Itshe lokuqala lingelinye.',
  'Essa pedra não encaixa na mesa.': 'Lelo tshe alingeni etafuleni.',
