  Mirar: 'Hlosa',
  Atirar: 'Dubula',
  Xadrez: 'I-chess',
  'Uma partida de xadrez inteira, com todas as regras. Quem abre fica com as brancas. A sala assiste.': 'Umdlalo ophelele we-chess, nayo yonke imithetho. Oqalayo udlala ngokumhlophe. Igumbi liyabuka.',
  'Xeque!': 'Cheki!',
  Dama: 'Indlovukazi',
  Torre: 'Inqaba',
  Bispo: 'Umbhishobhi',
  'Cozinha da toca': 'Ikhishi lomgodi',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Thatha izithako emabhokisini, uzisike ebhodini, uziphekele esitofini nasehhavini ngaphandle kokuzishisa, uzibeke epuletini bese uzidlulisa efasiteleni. Wonke umuntu uthola ama-oda afanayo: odlulisa amapuleti amaningi emizuzwini emi-3 uyawina.',
  'Pegar ou largar': 'Phakamisa noma ubeke phansi',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'Lo mdlalo udinga imidwebo ye-3D, engavulekanga kule divayisi.',
  'Este prato não é o pedido.': 'Leli puleti akusilo i-oda.',
  Kickflip: 'Kickflip',
  Grab: 'Grab',
  Manual: 'Manual',
  'Rolê do coelho': 'Uhambo lukanogwaja',
  'Um minuto na pista de skate. Pule, gire, faça grind nos corrimãos e emende as manobras num combo: cada manobra a mais multiplica os pontos, mas cair perde o combo inteiro.': 'Umzuzu owodwa epaki ye-skate. Gxuma, jikeleza, yenza i-grind ezinsimbini bese uxhumanisa amaqhinga abe yikhombo: iqhinga ngalinye elengeziwe liphindaphinda amaphuzu, kodwa ukuwa kulahlekisa ikhombo yonke.',
  Pausar: 'Misa okwesikhashana',
  'Caiu!': 'Uwile!',
  'Melhor combo: {n}': 'Ikhombo engcono kakhulu: {n}',
  'Trânsito da toca': 'Ithrafikhi Yomgodi',
  'Um minuto para soltar os carros do cruzamento sem deixar que batam. Fila cheia também custa pontos.': 'Umzuzu owodwa wokudedela izimoto empambanweni yemigwaqo zingashayisani. Ulayini ogcwele nawo ukudlela amaphuzu.',
  Liberar: 'Dedela',
  'Carrinhos da toca': 'Izimoto Zokudlala Zomgodi',
  'Uma pista de carrinhos de brinquedo com quatro faixas: o carro segue a faixa sozinho, e você só acelera. Acelerou demais na curva, ele sai voando e perde tempo. No Solo, contra o relógio, os fantasmas dos amigos e robôs.': 'Umzila wezimoto zokudlala onemizila emine: imoto ilandela umzila wayo yodwa, wena usheshisa nje. Uma usheshisa kakhulu ekhoneni, iyandiza iphume emzileni bese ilahlekelwa yisikhathi. Uwedwa: ubhekene nesikhathi, izipoki zabangane namarobhothi.',
  'Acelerar': 'Sheshisa',
  'Saiu da pista!': 'Iphumile emzileni!',
  'Saídas da pista: {n}': 'Ukuphuma emzileni: {n}',
  'Segure para acelerar e solte antes da curva: quando o carro treme, ele está no limite.': 'Bamba ukuze usheshise bese uyekela ngaphambi kwekhona: uma imoto iqhaqhazela, isemkhawulweni.',
  // O cômodo do quarto: a planta e as cores da parede e do piso (06/11/2026)
