  'Cubículo': 'Igumbi elincane',
  // a Ponte da toca (06/11/2026)
  'Ponte da toca': 'Ibhuloho Lomgodi',
  'Trinta segundos para montar uma ponte de madeira e aço. Ganha quem levar o tráfego até o outro lado gastando menos.': 'Imizuzwana engamashumi amathathu yokwakha ibhuloho ngezingodo nensimbi. Owinayo yilowo oweqisa izimoto ngezindleko eziphansi kakhulu.',
  'Pista': 'Umgwaqo',
  'Aço': 'Insimbi',
  'Testar': 'Ukuhlola',
  'Montar': 'Ukwakha',
  'Passou!': 'Kuphumelele!',
  '{n}% do caminho': '{n}% wendlela',
  'Gincana da toca': 'Umjaho wezithiyo womgodi',
  'Uma corrida de obstáculos em 3D: corra, pule e se equilibre por plataformas, esteiras, serras e varredores até a bandeira. Caiu, volta à última bandeira. No Solo, contra o relógio e os fantasmas dos amigos.': 'Umjaho wezithiyo we-3D: gijima, gxuma futhi ubambe ibhalansi phezu kwezinkundla, amabhande ahambayo, amasaha nezingalo ezizungezayo kuze kube sefulegini. Uma uwa, ubuyela efulegini lokugcina. Ku-Solo, ubhekene newashi nezipoki zabangane.',
  'Quedas: {n}': 'Ukuwa: {n}',
  'Tocar o sino: todos os trabalhadores para dentro do centro da vila': 'Shaya insimbi: zonke izisebenzi zingene esikhungweni sedolobhana',
  'Tocar o sino de novo: todos de volta ao trabalho': 'Shaya insimbi futhi: bonke babuyele emsebenzini',
  'Este lugar já está cheio.': 'Le ndawo isigcwele.',
  'Clássico': 'Okudala',
  'Colorido': 'Okunemibala',
  // Saúde do servidor: ações da Hetzner e diagnóstico do host
  "Diagnóstico do host": "Ukuhlolwa komsingathi",
  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Amalogi alinganiselwe e-Docker, SSH, logind ne-kernel avela ekuqaleni okuthathu kwakamuva. Angaqukatha amakheli e-IP.",
  "Atualizar diagnóstico": "Vuselela ukuhlola",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Akukabi bikho isithombe. Sizoqoqwa uma iphepha lokugcina livulwa ngokulandelayo.",
  "Coletado em {data}": "Kuqoqwe ngo-{data}",
  "Medido pela {nome}": "Kulinganiswe ngu-{nome}",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Izinombolo ezifanayo nezedeshibhodi yomhlinzeki. Kufaka idiski, iseva engayilinganisi yona ngokwayo.",
  "Ações no servidor": "Izenzo kuseva",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Umlando we-Hetzner: ukuvula, ukuvala nokuqala kabusha, kusuka kudeshibhodi noma ku-API. Ukuphazamiseka okungenasenzo lapha akuqalwanga ngalezi zindlela.",
  "Nenhuma ação registrada.": "Azikho izenzo ezirekhodiwe.",
  "Ligar o servidor": "Vula iseva",
  "Desligar o servidor": "Vala iseva",
  "Reiniciar o servidor": "Qala kabusha iseva",
  "Concluída": "Kuqediwe",
  "Falhou": "Kuhlulekile",
  "Em andamento": "Kuyaqhubeka",
  // O servidor fora do ar
  "503 — O servidor do Syden não está respondendo": "503 — Iseva ye-Syden ayiphenduli",
  "O Syden está fora do ar": "I-Syden ayisebenzi",
  "Não é a sua internet: o nosso servidor parou de responder. Quando ele voltar, esta tela some sozinha.": "Akuyona i-inthanethi yakho: iseva yethu iyekile ukuphendula. Uma ibuya, lesi sikrini sizonyamalala ngokwaso.",
  "OFFLINE — Sem conexão com a internet": "OFFLINE — Akukho ukuxhumana kwe-inthanethi",
  "Sem internet": "Ayikho i-inthanethi",
  "Quando a conexão voltar, esta tela some sozinha.": "Uma ukuxhumana kubuya, lesi sikrini sizonyamalala ngokwaso.",
  // O palco: esconder a faixa de baixo
  "Esconder os outros quadros": "Fihla amabhokisi amanye",
  "Mostrar os outros quadros": "Bonisa amabhokisi amanye",
