  // A caminha do gato
  "Caminha do gato": "Umbhede wekati",
  "Redonda e fofa, com a entrada mais baixa. O gato dorme aqui.": "Uyindilinga futhi uthambile, unomnyango ophansi. Ikati lilala lapha.",
