  'Seu palpite': "Ukuqagela kwakho",
  'Seu palpite está salvo. Dá para mudar até fechar.': "Ukuqagela kwakho kulondoloziwe. Ungakushintsha kuze kuvalwe.",
  // O fundo da câmera (16/11/2026)
  'Fundo da câmera': "Ingemuva lekhamera",
  'Desfocado': "Fiphalisa",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Kufiphalisa, kusule noma kushintshe lokho okubonakala ngemuva kwakho. Isithombe sekhamera asiphumi kukhompyutha yakho ngenxa yalokhu.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Okwemvelo",
  'Resolução': "Ukucaca",
  'Quadros por segundo': "Amafreyimu ngomzuzwana",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Ngesikhathi ukukhetha okuzenzakalelayo kuphazama: ukucaca namafreyimu kuhlala kunjengoba ukhethile, kusukela ekuqaleni kuze kube sekupheleni kokusakaza.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Imiphumela yezwi neyekhamera eyenziwa kukhompyutha yakho, ngaphandle kokuthumela lutho kuseva.",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Ijele Lomgodi",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Dlulani ndawonye emgodini wenkosi yamakhowe: amakamelo agcwele izilwane, ibhokisi elinesanqante esihamba sibuye, izinkinobho ezidinga abantu ababili ngesikhathi esisodwa, nomnyango okhiyiwe. Abantu abangu-1 kuya ku-4.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Indandatho Yomgodi",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Isibhakela sokusabela ngokushesha bebhekene nabaphikisi abathathu bekhompyutha. Funda uphawu lwesibhakela ngasinye, gwema noma uvikele, bese ushaya esikhaleni. Ukushaya lapho iglavu icwebezela kugcwalisa inkanyezi yesibhakela esinamandla.",
  'Esquivar': "Gwema",
  'Abaixar e defender': "Goba uvikele",
  'Socar': "Shaya",
  'Soco forte': "Isibhakela esinamandla",
  'Aperte os socos para levantar!': "Cindezela izibhakela ukuze usukume!",
  'Lutas vencidas: {n}': "Imincintiswano owayiwinile: {n}",
  'Nocaute!': "Ukuwisa!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Umzila Wezinkanyezi",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Onogwaja emikhunjini yasemkhathini phezu kwendawo yeplanethi nasemkhathini: dubula, bamba ukudubula ukuze ukhiye okuhlosiwe, phenduka ukuze uphambukise izinhlamvu, ukhethe indlela empambanweni. Iqembu lindiza umzila ofanayo, futhi umphathi ulinde ekugcineni.",
  'Pirueta': "Ukuphenduka",
  'Segure para travar a mira': "Bamba ukuze ukhiye",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Ikhomando Likaroti",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Gijima futhi udubule neqembu: isibhamu sekharoti siqondisa ezinhlangothini eziyisishiyagalombili, ibhomu lesandla livula indlela, futhi okhulula onogwaja abancane abavalelwe ezikhejini uthola amandla engeziwe. Udrako ulinde ekugcineni: abantu abangu-1 kuya ku-4.",
  'Andar e mirar': "Hamba futhi uqondise",
  'Granada': "Ibhomu lesandla",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "I-Pinball yengadi",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Itafula le-pinball engadini yemifino: bamba isipringi, yenza ibhola leqe kumaklabishi bese uwisa izaqathe ezintathu ukuze ukhanyise umgodi kanogwaja, okhulula elinye ibhola. Amabhola amathathu, futhi ukunyakazisa kakhulu kukhiya itafula.",
  'Palhetas': "Iziqhubi",
  'Mola': "Isipringi",
  'Sacudir': "Nyakazisa",
  'Bola salva!': "Ibhola lisindisiwe!",
  'Multibola!': "Amabhola amaningi!",
  'Mesa travada!': "Itafula likhiyiwe!",
  'Cuidado!': "Qaphela!",
  'Recordes dos amigos': "Amarekhodi abangane",
