  'Desafios de voo: asa-delta, mochila a jato e paraquedas. Passe pelos anéis e pouse no alvo, perto do centro e de leve.': 'Izinselelo zokundiza: i-hang glider, isikhwama se-jet ne-parachute. Ndiza ngezindandatho bese wehlela kumgomo, eduze nenkaba futhi kancane.',
