  // Lendas da Toca (16/11/2026)
  'Lendas da Toca': "Izinganekwane Zomgodi",
  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "I-RPG emfushane yamajika: wonke umuntu ulawula iqhawe elilodwa leqembu. Khethani ndawonye, nihlanganise ukuhlasela futhi nehlule udrako wenqaba.",
