  // Bichos da Toca (16/11/2026)
  'Bichos da Toca': "Izilwane Zomgodi",
  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "Zulazula emasimini, wenze ubungane nezilwane ezisotshanini olude ngesanqante, wakhe iqembu elifika kwayisithupha. Nqoba inselele yendlu eluhlaza okwesibhakabhaka, bese ulwa neqembu lomngane egumbini.",
  'Gota': "Iconsi",
