  "{nome}: {tiros} tiros, {pct}% de acerto": "{nome}: izibhamu ezingu-{tiros}, {pct}% ziyashaya",
  "1 contra 3": "1 ngokumelene no-3",
  "2 contra 2": "2 ngokumelene no-2",
  "A armadilha de {nome} disparou: quem sai junto?": "Isicupho sika-{nome} sicishekile: ubani ophuma naye?",
  "A largada precisa de uma reta.": "Isiqalo sidinga umugqa oqondile.",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "ISimangaliso sika-{nome} simile imizuzu emi-2.",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "Isimo esifanayo okwesithathu kuyalingana, kanjalo nokuhamba okungu-20 kwezindlovukazi kuphela ngaphandle kokudla.",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "Ebusuku, bona ukuthi abantu-mpisi bahlasele bani. Umuthi owodwa usindisa lowo muntu kanti omunye ukhipha othile emdlalweni; ngamunye usebenza kanye.",
  "A partida se desencontrou entre os computadores e foi encerrada.": "Umdlalo awusahambisani phakathi kwamakhompyutha futhi uvaliwe.",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "Itshe eliqeda ukuhamba emgqeni wokugcina liba yindlovukazi, ehamba lonke ixhaxha.",
  "A pista ainda não fecha a volta.": "Umgwaqo awukaluvali umjikelezo.",
