  "A turma age antes nas duas rodadas seguintes.": "Iqembu lisebenza kuqala emizuliswaneni emibili elandelayo.",
  "A turma está decidindo.": "Iqembu liyanquma.",
  "A turma inteira leva bem menos dano nesta rodada.": "Lonke iqembu lilimala kancane kakhulu kulo mzuliswano.",
  "A turma recupera vida no fim de três rodadas.": "Iqembu libuyisa impilo ekupheleni kwemizuliswano emithathu.",
