  // Os mini-games e as insígnias (19/11/2026)
  "{nome} terminou uma Maravilha: defenda-a por 2 minutos!": "U-{nome} uqede iSimangaliso: sivikele imizuzu emi-2!",
  "{nome} terminou uma Maravilha.": "U-{nome} uqede iSimangaliso.",
  "A Maravilha da outra equipe ficou de pé por 2 minutos.": "Isimangaliso seqembu elinye simile imizuzu emi-2.",
  "A Maravilha da sua equipe ficou de pé por 2 minutos.": "Isimangaliso seqembu lakho simile imizuzu emi-2.",
  "A outra equipe derrubou os dois centros da vila de vocês.": "Iqembu elinye liwisile zombili izikhungo zedolobhana zenu.",
  "A outra equipe desistiu.": "Iqembu elinye lihoxile.",
  "A outra equipe saiu da sala.": "Iqembu elinye liphumile egumbini.",
  "A sua equipe desistiu.": "Iqembu lakho lihoxile.",
  "A sua equipe ficou fora da sala por muito tempo.": "Iqembu lakho lihlale ngaphandle kwegumbi isikhathi eside.",
  "Duas equipes de dois. Os robôs completam os lugares que faltam.": "Amaqembu amabili abantu ababili. Amarobhothi agcwalisa izindawo ezisele.",
  "Gênero": "Ubulili",
  "Levadiça": "Ibhuloho eliphakanyiswayo",
  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "Azikabikho izingxoxo. Thinta umuntu ohlwini lwabantu lomphakathi bese ukhetha \"Thumela umlayezo\".",
  "Varia": "Kuyahluka",
  "Vitória de {nomes}": "Ukunqoba kuka-{nomes}",
  "Vocês derrubaram os dois centros da vila da outra equipe.": "Niwisile zombili izikhungo zedolobhana zeqembu elinye.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "Idolobha okungekho muntu olithengayo liya endalini. Ukubambisa idolobha kunikeza imali, kodwa alikhokhisi irenti.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "Icebo likhanyisa ucezu okufanele lunyakaze. Inkinga exazululwe ngecebo ayitholi maphuzu; emjahweni, isusa imizuzwana eyi-10.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "I-manilha yinani elilandela elekhadi elivuliwe futhi ishaya wonke. Phakathi kwazo: amadayimane, amafosholo, izinhliziyo nezihlahla, i-zap.",
  "A última nave de cada volta sai.": "Umkhumbi wokugcina kumjikelezo ngamunye uyaphuma.",
  "Abaixar": "Khothama",
  "Acertos em sequência: {n}": "Okulungile okulandelanayo: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Hamba ngedayisi bese uthenga inhloko-dolobha lapho ume khona. Omi edolobheni lomunye ukhokha irenti.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Umugqa ngamunye, ikholomu nebhlokhi ka-3 × 3 kunezinombolo ezi-1 kuya ku-9, ngaphandle kokuphindaphinda.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Ngamunye uthola amakhadi ama-3. Owina imijikelezo emi-2 kwemi-3 uthatha isandla.",
  "Campeonato": "Umqhudelwano",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Ngamaphuzu angu-11, iqembu libona amakhadi bese linquma ukuthi lizodlala isandla seshumi nanye. Ofinyelela ku-12 uyawina.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Uma unesifunda sonke, yakha izakhiwo ezifika ku-4: irenti ikhuphuka ngesinye nesinye.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Uma unezinkanyezi, isibhakela esinamandla (★) sizisebenzisa zonke ngesikhathi esisodwa futhi sibuhlungu kakhulu.",
  "Dica": "Icebo",
  "Dica: este problema não pontua": "Icebo: le nkinga ayitholi maphuzu",
  "Dica: tira 10 segundos": "Icebo: lisusa imizuzwana eyi-10",
  "Eliminação": "Ukukhishwa",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Beka itshe ekugcineni kwetafula elinenombolo efanayo.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Khetha isikwele bese inombolo. Ipensela libhalela wena kuphela.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Gwema isibhakela bese ushaya ngokushesha: lokho kuwukuhlasela kabusha, futhi kunikeza inkanyezi.",
  "Fora da corrida na volta {n}.": "Uphumile emjahweni emjikelezweni we-{n}.",
  "Força das cartas": "Amandla amakhadi",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Owina yilowo onengcebo enkulu ekugcineni kwemijikelezo, noma osele.",
  "Iniciante": "Oqalayo",
  "Mestre": "Ingcweti",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "Ngokulandelana, okulungile ngakunye kuletha inkinga enzima kakhulu, futhi iphutha lokuqala liyaqeda.",
  "O número pequeno no botão diz quantos ainda faltam.": "Inombolo encane enkinobhweni ikhombisa ukuthi zingaki ezisasele.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "Imizila emihlanu ilandelana ngokumelene nekhompyutha, ngamaphuzu.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Cela i-truco futhi isandla sibiza u-3. Ophendulayo uyamukela, abaleke noma akhuphule aye ku-6, 9 noma 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Oqedayo usala engenawo amatshe futhi uthatha amaphuzu ezandla zabanye. Uma umdlalo uvalekile, uthatha onamaphuzu ambalwa esandleni.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Uma lingekho itshe elifanelekayo, thenga. Uma kungekho okuthengwayo, ithuba liyadlula.",
  "Sequência": "Ukulandelana",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Shaya lapho igilavu ikhanya: isibhakela siyama futhi uthola inkanyezi.",
  "Treino livre": "Ukuzilolonga ngokukhululeka",
  // Os mini-games e as insígnias (19/11/2026)
  "{n} capitais": "Izinhloko-dolobha ezingu-{n}",
  "{nome} aprendeu {golpe}!": "U-{nome} ufunde i-{golpe}!",
  "{nome} deu {bicho} para você cuidar.": "U-{nome} ukunike i-{bicho} ukuze uyinakekele.",
  "{nome} esqueceu {antigo} e aprendeu {golpe}.": "U-{nome} ukhohlwe i-{antigo} wafunda i-{golpe}.",
  "{nome} parou com tudo valendo: +{n}": "U-{nome} ubize i-STOP futhi zonke izimpendulo zamukelekile: +{n}",
  "{nome} quer aprender {golpe}, mas já sabe 4 golpes.": "U-{nome} ufuna ukufunda i-{golpe}, kodwa usevele azi izinhlaselo ezi-4.",
  "{nome} tomou erva-doce e ficou bem.": "U-{nome} uphuze ifenela waba ngcono.",
  "{nome} vai voltar para o mato. Tem certeza?": "U-{nome} uzobuyela ehlathini. Uqinisekile?",
  "A geladeira pifou: pague {valor}.": "Ifriji ifile: khokha {valor}.",
  "A pedra não come para trás": "Itshe alidli libuyela emuva",
  "A restituição do imposto caiu na conta: receba {valor}.": "Imbuyiselo yentela ingene ku-akhawunti: thola {valor}.",
  "A toca está vazia.": "Umgodi awunalutho.",
  "A turma fez uma vaquinha: cada um te dá {valor}.": "Iqembu liqoqe imali: ngamunye ukunika {valor}.",
  "Aceitar que não vale": "Vuma ukuthi akuvumelekile",
  "Achou um atalho: avance 5 casas.": "Uthole indlela emfushane: qhubekela phambili izikwele ezi-5.",
  "Alta temporada em {lugares}: os aluguéis dobram por uma rodada.": "Isikhathi sezivakashi e-{lugares}: irenti iphindeka kabili umzuliswano owodwa.",
  "As duas diagonais também têm os números de 1 a 9.": "Imigqa emibili ehlangene nayo inezinombolo ezisuka ku-1 kuya ku-9.",
  "As escuras não fazem dois três abertos de uma vez": "Abamnyama abenzi amathathu avulekile amabili ngesikhathi esisodwa",
