  "Com as batidas especiais, bater com carroça ou com a pedra que serve nas duas pontas vale o dobro; a carroça nas duas pontas, o quádruplo.": "Ngokuqeda okukhethekile, ukuqeda ngetshe elikabili noma ngetshe elingena emaphethelweni omabili kuphindeka kabili; itshe elikabili elingena emaphethelweni omabili, kane.",
