  "Saara": "ISahara",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Kuvela isilwane esiyimfihlo, bese ngamunye eqagela ezinye. Ukuqagela ngakunye kubonisa okufanayo nesiyimfihlo: isigaba, ukudla, lapho sihlala khona nesisindo. Oqagela kahle ngokuqagela okumbalwa uthola amaphuzu amaningi.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Kuvela i-dinosaur eyimfihlo, bese ngamunye eqagela ezinye. Ukuqagela ngakunye kubonisa okufanayo neyimfihlo: inkathi, ukudla, iqembu, ubude nalapho yatholakala khona. Oqagela kahle ngokuqagela okumbalwa uthola amaphuzu amaningi.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Kuvela isakhi samakhemikhali esiyimfihlo, bese ngamunye eqagela ezinye. Ukuqagela ngakunye kubonisa okufanayo nesiyimfihlo: umndeni, isimo, inkathi, iqembu nenombolo ye-athomu. Oqagela kahle ngokuqagela okumbalwa uthola amaphuzu amaningi.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Kuvela isifundazwe saseBrazil esiyimfihlo, bese ngamunye eqagela ezinye. Ukuqagela ngakunye kubonisa ibanga nendlela eya kwesiyimfihlo, isifunda, inani labantu, ubukhulu bendawo, ugu nomngcele nelinye izwe. Oqagela kahle ngokuqagela okumbalwa uthola amaphuzu amaningi.",
